using System;
using System.Collections.Generic;
using System.Collections.Immutable;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Threading.Tasks;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Diagnostics;

public class A5_F2_AnalyzerClosedGenericStructFromReferenceTests
{
    private const string ReferencedSource = """
using System;
using MessagePack;

namespace RefLib
{
    public struct PlainStruct<T>
    {
        public T Value;
    }

    public record struct PlainRecordStruct<T1, T2>(T1 A, T2 B);

    [MessagePackObject]
    public struct KeyedStruct<T1, T2>
    {
        [Key(0)]
        public T1 First { get; set; }

        [Key(1)]
        public T2 Second { get; set; }
    }

    [MessagePackObject]
    public struct KeyedSingleStruct<T>
    {
        [Key(0)]
        public T Value { get; set; }
    }

    [MessagePackObject]
    public record struct KeyedRecordStruct<T>([property: Key(0)] T Value);

    public class Outer<T>
    {
        public struct Inner<U>
        {
            public T A;
            public U B;
        }
    }
}
""";

    private readonly ITestOutputHelper testOutputHelper;

    public A5_F2_AnalyzerClosedGenericStructFromReferenceTests(ITestOutputHelper testOutputHelper)
    {
        this.testOutputHelper = testOutputHelper;
    }

    [Fact]
    public async Task A5_F2_KeyedClosedGenericStructsFromReference_DoNotCrashAnalyzer()
    {
        string usageSource = """
using System;
using MessagePack;
using RefLib;

namespace TempProject
{
    [MessagePackObject]
    public class MyObject
    {
        [Key(0)]
        public KeyedStruct<int, string> A { get; set; }

        [Key(1)]
        public KeyedSingleStruct<long> B { get; set; }

        [Key(2)]
        public KeyedRecordStruct<int> C { get; set; }

        [Key(3)]
        public KeyedStruct<KeyedSingleStruct<int>, string> D { get; set; }
    }
}
""";

        await this.RunAndAssertNoAnalyzerCrashAsync(usageSource);
    }

    [Fact]
    public async Task A5_F2_PlainClosedGenericStructsFromReference_DoNotCrashAnalyzer()
    {
        string usageSource = """
using System;
using MessagePack;
using RefLib;

namespace TempProject
{
    [MessagePackObject]
    public class MyObject
    {
        [Key(0)]
        public PlainStruct<int> A { get; set; }

        [Key(1)]
        public PlainRecordStruct<int, string> B { get; set; }

        [Key(2)]
        public Outer<int>.Inner<string> C { get; set; }
    }
}
""";

        await this.RunAndAssertNoAnalyzerCrashAsync(usageSource);
    }

    private static List<MetadataReference> GetBaseReferences()
    {
        var paths = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);

        void AddPath(string? path)
        {
            if (string.IsNullOrEmpty(path) || !File.Exists(path))
            {
                return;
            }

            string name = Path.GetFileName(path!);
            if (paths.ContainsKey(name))
            {
                return;
            }

            try
            {
                AssemblyName.GetAssemblyName(path!);
            }
            catch
            {
                return;
            }

            paths[name] = path!;
        }

        if (AppContext.GetData("TRUSTED_PLATFORM_ASSEMBLIES") is string tpa)
        {
            foreach (string p in tpa.Split(Path.PathSeparator))
            {
                AddPath(p);
            }
        }

        foreach (Assembly asm in AppDomain.CurrentDomain.GetAssemblies())
        {
            if (asm.IsDynamic)
            {
                continue;
            }

            string location;
            try
            {
                location = asm.Location;
            }
            catch
            {
                continue;
            }

            AddPath(location);
        }

        string baseDir = AppContext.BaseDirectory;
        if (Directory.Exists(baseDir))
        {
            foreach (string p in Directory.GetFiles(baseDir, "MessagePack*.dll"))
            {
                AddPath(p);
            }
        }

        return paths.Values.Select(p => (MetadataReference)MetadataReference.CreateFromFile(p)).ToList();
    }

    private static ImmutableArray<DiagnosticAnalyzer> GetMessagePackAnalyzers()
    {
        Assembly assembly = typeof(MessagePack.SourceGenerator.MessagePackGenerator).Assembly;
        Type[] types;
        try
        {
            types = assembly.GetTypes();
        }
        catch (ReflectionTypeLoadException ex)
        {
            types = ex.Types.Where(t => t is not null).Select(t => t!).ToArray();
        }

        var result = ImmutableArray.CreateBuilder<DiagnosticAnalyzer>();
        foreach (Type t in types)
        {
            if (t.IsAbstract || !typeof(DiagnosticAnalyzer).IsAssignableFrom(t))
            {
                continue;
            }

            var attr = t.GetCustomAttribute<DiagnosticAnalyzerAttribute>();
            if (attr is null || !attr.Languages.Contains(LanguageNames.CSharp))
            {
                continue;
            }

            if (t.GetConstructor(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic, null, Type.EmptyTypes, null) is null)
            {
                continue;
            }

            result.Add((DiagnosticAnalyzer)Activator.CreateInstance(t, nonPublic: true)!);
        }

        return result.ToImmutable();
    }

    private async Task RunAndAssertNoAnalyzerCrashAsync(string usageSource)
    {
        var parseOptions = new CSharpParseOptions(LanguageVersion.Latest);
        var compilationOptions = new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary);
        List<MetadataReference> baseReferences = GetBaseReferences();

        CSharpCompilation refCompilation = CSharpCompilation.Create(
            "RefLib",
            new[] { CSharpSyntaxTree.ParseText(ReferencedSource, parseOptions) },
            baseReferences,
            compilationOptions);

        MetadataReference refLib;
        using (var ms = new MemoryStream())
        {
            var emitResult = refCompilation.Emit(ms);
            Assert.True(
                emitResult.Success,
                "Referenced assembly failed to compile: " + string.Join(Environment.NewLine, emitResult.Diagnostics.Where(d => d.Severity == DiagnosticSeverity.Error)));
            refLib = MetadataReference.CreateFromImage(ms.ToArray());
        }

        CSharpCompilation compilation = CSharpCompilation.Create(
            "TempProject",
            new[] { CSharpSyntaxTree.ParseText(usageSource, parseOptions) },
            baseReferences.Concat(new[] { refLib }),
            compilationOptions);

        var compileErrors = compilation.GetDiagnostics().Where(d => d.Severity == DiagnosticSeverity.Error).ToList();
        Assert.True(compileErrors.Count == 0, "Usage compilation has errors: " + string.Join(Environment.NewLine, compileErrors));

        ImmutableArray<DiagnosticAnalyzer> analyzers = GetMessagePackAnalyzers();
        Assert.NotEmpty(analyzers);

        var exceptions = new List<string>();
        var options = new CompilationWithAnalyzersOptions(
            new AnalyzerOptions(ImmutableArray<AdditionalText>.Empty),
            (ex, analyzer, diag) =>
            {
                lock (exceptions)
                {
                    exceptions.Add($"{analyzer.GetType().Name}: {ex}");
                }
            },
            concurrentAnalysis: false,
            logAnalyzerExecutionTime: false);

        var withAnalyzers = compilation.WithAnalyzers(analyzers, options);
        ImmutableArray<Diagnostic> diagnostics = await withAnalyzers.GetAnalyzerDiagnosticsAsync();

        foreach (Diagnostic d in diagnostics)
        {
            this.testOutputHelper.WriteLine(d.ToString());
        }

        Assert.True(exceptions.Count == 0, "Analyzer threw: " + string.Join(Environment.NewLine, exceptions));

        var crashes = diagnostics.Where(d => d.Id == "AD0001").ToList();
        Assert.True(crashes.Count == 0, "Analyzer crashed: " + string.Join(Environment.NewLine, crashes.Select(d => d.GetMessage())));
        Assert.DoesNotContain(diagnostics, d => d.GetMessage().Contains("IndexOutOfRangeException"));
    }
}
